#pragma once
#include "PluginProcessor.h"
namespace MavenUI {
inline void setParameter(SynthMavenProcessor&p,const juce::String&id,float value){if(auto*parameter=p.parameters.getParameter(id)){parameter->beginChangeGesture();parameter->setValueNotifyingHost(juce::jlimit(0.f,1.f,value));parameter->endChangeGesture();}}
inline void learnMenu(SynthMavenProcessor&p,const juce::String&id,juce::Component&target){juce::PopupMenu menu;menu.addSectionHeader(p.mappingDescription(id));menu.addItem(1,"MIDI Learn");menu.addItem(2,"Remove mapping");juce::Component::SafePointer<juce::Component>safe(&target);menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(&target),[safe,&p,id](int action){if(!safe)return;if(action==1)p.beginLearn(id);if(action==2)p.removeMapping(id);});}
struct SplitPopup:juce::Component {
 SynthMavenProcessor&p;int layer;juce::ComboBox mode,side,channel,point;juce::Label title,pointLabel,sideLabel,channelLabel;
 SplitPopup(SynthMavenProcessor&proc,int l):p(proc),layer(l){for(auto*c:std::initializer_list<juce::Component*>{&title,&mode,&point,&side,&channel,&pointLabel,&sideLabel,&channelLabel})addAndMakeVisible(c);title.setText("LAYER "+juce::String(l+1)+" / KEYBOARD ROUTING",juce::dontSendNotification);mode.addItem("Layer - entire keyboard",1);mode.addItem("Split - selected zone",2);side.addItem("Lower: up to split point",1);side.addItem("Upper: above split point",2);channel.addItem("OMNI",1);for(int i=1;i<=16;i++)channel.addItem("CH "+juce::String(i),i+1);auto raw=[&](const char*key){return p.parameters.getRawParameterValue(p.layerId(l,key))->load();};mode.setSelectedId(raw("split")>=.5f?2:1);side.setSelectedId(raw("splitSide")>=.5f?2:1);channel.setSelectedItemIndex(juce::roundToInt(raw("channel")*16));for(int note=0;note<128;note++)point.addItem(juce::MidiMessage::getMidiNoteName(note,true,true,4),note+1);point.setSelectedId(juce::roundToInt(raw("splitPoint")*127)+1);pointLabel.setText("SPLIT POINT",juce::dontSendNotification);sideLabel.setText("ZONE",juce::dontSendNotification);channelLabel.setText("MIDI INPUT",juce::dontSendNotification);mode.onChange=[this]{setParameter(p,p.layerId(layer,"split"),mode.getSelectedId()==2?1.f:0.f);refresh();};side.onChange=[this]{setParameter(p,p.layerId(layer,"splitSide"),side.getSelectedId()==2?1.f:0.f);};point.onChange=[this]{setParameter(p,p.layerId(layer,"splitPoint"),(point.getSelectedId()-1)/127.f);};channel.onChange=[this]{setParameter(p,p.layerId(layer,"channel"),channel.getSelectedItemIndex()/16.f);};refresh();setSize(300,238);}
 void refresh(){bool split=mode.getSelectedId()==2;point.setEnabled(split);side.setEnabled(split);}
 void resized()override{title.setBounds(12,8,276,24);mode.setBounds(12,40,276,30);pointLabel.setBounds(12,78,92,26);point.setBounds(104,78,184,26);sideLabel.setBounds(12,116,62,26);side.setBounds(76,116,212,30);channelLabel.setBounds(12,163,92,26);channel.setBounds(104,163,184,30);}
};
struct Meter:juce::Component{std::atomic<float>&source;float value=0;explicit Meter(std::atomic<float>&s):source(s){}void refresh(){value=juce::jmax(source.load(),value*.82f);repaint();}void paint(juce::Graphics&g)override{g.fillAll(juce::Colour(0xff10151d));auto r=getLocalBounds().toFloat().reduced(2);float fraction=juce::jlimit(0.f,1.f,(juce::Decibels::gainToDecibels(value,-60.f)+60)/60);g.setColour(value>=1?juce::Colour(0xffff925d):juce::Colour(0xff56e5c7));g.fillRect(r.removeFromBottom(r.getHeight()*fraction));}};
struct MixerStrip:juce::Component{
 SynthMavenProcessor&p;int layer;bool master;std::function<void(int)>editLayer;juce::TextButton select,octDown{"-"},octUp{"+"},route{"LAYER"},mute{"M"},solo{"S"},edit{"EDIT"};juce::ToggleButton enabled{"ON"};juce::Label octave,instrument,number;juce::Slider pan,fader;Meter meter;
 std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>panAttach,gainAttach;std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>muteAttach,soloAttach,enableAttach;
 MixerStrip(SynthMavenProcessor&proc,int l,std::function<void(int)>callback):p(proc),layer(l),master(l==8),editLayer(std::move(callback)),select(master?"MASTER":"L"+juce::String(l+1)),meter(proc.meters[(size_t)l]){
  for(auto*c:std::initializer_list<juce::Component*>{&select,&pan,&fader,&meter,&mute,&instrument})addAndMakeVisible(c);for(auto*b:{&mute,&solo})b->setClickingTogglesState(true);
  auto id=[&](const char*key){return master?juce::String("master")+(juce::String(key)=="gain"?"Gain":juce::String(key)=="pan"?"Pan":"Mute"):p.layerId(layer,key);};
  pan.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);pan.setTextBoxStyle(juce::Slider::TextBoxBelow,false,68,18);pan.setDoubleClickReturnValue(true,.5);pan.setRange(0,1);fader.setComponentID("mixerFader");fader.setSliderStyle(juce::Slider::LinearVertical);fader.setTextBoxStyle(juce::Slider::TextBoxAbove,false,76,24);fader.setRange(0,1);fader.setDoubleClickReturnValue(true,1);panAttach=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.parameters,id("pan"),pan);gainAttach=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.parameters,id("gain"),fader);muteAttach=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,id("mute"),mute);
  pan.textFromValueFunction=[](double v){return std::abs(v-.5)<.005?juce::String("C"):juce::String(juce::roundToInt(std::abs(v-.5)*200))+(v<.5?" L":" R");};fader.textFromValueFunction=[](double v){return v<=.00001?juce::String("-inf dB"):juce::String(juce::Decibels::gainToDecibels(v),1)+" dB";};fader.valueFromTextFunction=[](const juce::String&s){return s.contains("inf")?0.:juce::Decibels::decibelsToGain(s.getDoubleValue());};fader.setSkewFactorFromMidPoint(.1);pan.updateText();fader.updateText();instrument.setJustificationType(juce::Justification::centred);instrument.setFont(juce::Font(11,juce::Font::bold));mute.setTooltip("Mute this "+juce::String(master?"mix":"layer"));
  if(!master){for(auto*c:std::initializer_list<juce::Component*>{&octDown,&octUp,&octave,&route,&solo,&enabled,&edit})addAndMakeVisible(c);octave.setJustificationType(juce::Justification::centred);octave.setFont(11);soloAttach=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,p.layerId(layer,"solo"),solo);enableAttach=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,p.layerId(layer,"enabled"),enabled);octDown.onClick=[this]{shift(-12);};octUp.onClick=[this]{shift(12);};select.onClick=[this]{p.selectLayer(layer);};edit.onClick=[this]{editLayer(layer);};route.onClick=[this]{auto*parent=getTopLevelComponent();juce::CallOutBox::launchAsynchronously(std::make_unique<SplitPopup>(p,layer),parent->getLocalArea(&route,route.getLocalBounds()),parent);};}
  addMouseListener(this,true);refresh();
 }
 void shift(int semitones){auto id=p.layerId(layer,"transpose");float current=p.parameters.getRawParameterValue(id)->load();setParameter(p,id,current+semitones/48.f);refresh();}
 void mouseDown(const juce::MouseEvent&e)override{if(!e.mods.isPopupMenu())return;bool isPan=e.originalComponent==&pan||pan.isParentOf(e.originalComponent);learnMenu(p,master?(isPan?"masterPan":"masterGain"):p.layerId(layer,isPan?"pan":"gain"),*this);}
 void refresh(){meter.refresh();if(master){instrument.setText("STEREO OUT",juce::dontSendNotification);return;}float tr=p.parameters.getRawParameterValue(p.layerId(layer,"transpose"))->load();int semitones=juce::roundToInt(tr*48)-24;octave.setText((semitones>0?"+":"")+juce::String(semitones/12.f,1)+" OCT",juce::dontSendNotification);octDown.setEnabled(semitones>-24);octUp.setEnabled(semitones<24);bool split=p.parameters.getRawParameterValue(p.layerId(layer,"split"))->load()>=.5f;route.setButtonText(split?"SPLIT":"LAYER");instrument.setText(p.displayName(layer),juce::dontSendNotification);instrument.setTooltip(p.layerInstrument(layer)+" / "+p.displayName(layer));select.setToggleState(p.selectedLayer.load()==layer,juce::dontSendNotification);}
 void resized()override{int w=getWidth(),h=getHeight();select.setBounds(5,7,w-10,25);if(!master){octDown.setBounds(5,39,25,25);octUp.setBounds(w-30,39,25,25);octave.setBounds(31,39,w-62,25);route.setBounds(5,72,w-10,26);enabled.setBounds(6,100,w-12,24);}pan.setBounds(6,130,w-12,83);fader.setBounds(6,215,w-28,h-310);meter.setBounds(w-18,244,9,h-339);mute.setBounds(6,h-86,master?w-12:(w-18)/2,27);if(!master){solo.setBounds(w/2+2,h-86,(w-18)/2,27);edit.setBounds(6,h-52,w-12,23);}instrument.setBounds(5,h-27,w-10,22);}
 void paint(juce::Graphics&g)override{g.setColour(master?juce::Colour(0xff24303e):juce::Colour(0xff1a222e));g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(1),5);g.setColour(juce::Colour(0xff2b3747));g.drawVerticalLine(getWidth()-1,5,(float)getHeight()-5);}
};
struct MixerPanel:juce::Component{juce::OwnedArray<MixerStrip>strips;MixerPanel(SynthMavenProcessor&p,std::function<void(int)>edit){for(int i=0;i<9;i++)addAndMakeVisible(strips.add(new MixerStrip(p,i,edit)));}void refresh(){for(auto*s:strips)s->refresh();}void resized()override{int width=getWidth()/9;for(int i=0;i<9;i++)strips[i]->setBounds(i*width,0,i==8?getWidth()-8*width:width-3,getHeight());}};
}
